import { gsap } from 'gsap';
import { ParallaxScroll } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Array<{event:string,effect:string}>} [behaviors]
 * @property {any} [intent]
 * @property {any} [visualSpec]
 * @property {any} [textContent]
 * @property {any} [colors]
 * @property {any} [typography]
 * @property {any} [position]
 * @property {any} [rotation]
 * @property {any} [scale]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture: (url:string)=>Promise<any> }} textureLoader
 * @property {{ loadGLB: (url:string)=>Promise<any> }} glbLoader
 * @property {{ videoLoader?: { loadVideo: (url:string)=>Promise<any> } }} videoLoader
 * @property {{ fontAtlas: { createText: (content:string, opts?:any)=>any } }} fontAtlas
 * @property {{ emit: (event:string, payload:any)=>void, tier?:string, primitives: Record<string, (target:any, params:any)=>{ timeline:any, cleanup:()=>void }> }} ctx
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  /** @type {any} */
  const root = new Group();

  // -----------------------------
  // Load GLB mesh (asynchronous)
  // -----------------------------
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (gltf && gltf.scene) {
        root.add(gltf.scene);
      }
    }).catch(() => {
      // fail silently – visual spec requires the mesh, but loader errors are ignored here
    });
  }

  // -----------------------------
  // Apply cinematic primitives
  // -----------------------------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // -----------------------------
  // Interaction timelines
  // -----------------------------
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(root.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });

  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  }).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.3,
    ease: 'power2.out',
  });

  // -----------------------------
  // Event handlers registration
  // -----------------------------
  root.userData.handlers = {};

  // Hover – rise-in
  root.userData.handlers.hover = () => {
    hoverTL.play(0);
  };
  // Unhover – reverse rise-in
  root.userData.handlers.unhover = () => {
    hoverTL.reverse();
  };
  // Click – emit navigation event + press feedback
  root.userData.handlers.click = () => {
    ctx.emit('hub-home.select', {});
    pressTL.play(0);
  };

  // -----------------------------
  // Cleanup routine
  // -----------------------------
  root.userData.cleanup = () => {
    // Stop timelines
    hoverTL.kill();
    pressTL.kill();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Dispose geometries and materials from loaded GLTF
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m && m.dispose && m.dispose());
        } else if (obj.material && obj.material.dispose) {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
